  let mouse = uniforms.mouseVelocity.xy;
  let velocity = uniforms.mouseVelocity.zw;
  let time = uniforms.timingHover.x;
  let hover = uniforms.timingHover.y;
  let idleRadius = uniforms.timingHover.z;
  let hoverRadius = uniforms.timingHover.w;
  let velocityGain = uniforms.velocityAmbient.x;
  let ambientStrength = uniforms.velocityAmbient.y;
  let ambientSpeed = uniforms.velocityAmbient.z;
  let ambientFrequency = uniforms.ambientDrag.xy;
  let dragStrength = uniforms.ambientDrag.z;
  let dragVelocityStrength = uniforms.ambientDrag.w;
  let interactionDirection = uniforms.interaction.x;
  let pressureStrength = uniforms.interaction.y;
  let swirlStrength = uniforms.interaction.z;
  let radialStrength = uniforms.interaction.w;
  let radialFrequency = uniforms.radialEdge.x;
  let radialSpeed = uniforms.radialEdge.y;
  let uvClampInset = uniforms.radialEdge.z;
  let edgeProtection = uniforms.radialEdge.w;
  let rippleStrength = uniforms.rippleSettings.x;
  let hasActiveRipple = uniforms.rippleSettings.y;
  let interactionActive = uniforms.rippleSettings.z;

