    smoothstep(0.0, edgeProtection, uv.x) *
    smoothstep(0.0, edgeProtection, uv.y) *
    smoothstep(0.0, edgeProtection, 1.0 - uv.x) *
    smoothstep(0.0, edgeProtection, 1.0 - uv.y);
  let speed = min(length(velocity) * velocityGain, 1.0);

