      getRippleDisplacement(uv, uniforms.ripple1.xy, uniforms.ripple1.z) +
      getRippleDisplacement(uv, uniforms.ripple2.xy, uniforms.ripple2.z) +
      getRippleDisplacement(uv, uniforms.ripple3.xy, uniforms.ripple3.z)
